/**
 * Definition for a binary tree node.
 * class TreeNode {
 *      constructor(val = 0, left = null, right = null){
 *          this.data = val;
 *          this.left = null;
 *          this.right = null;
 *      }
 * }
 **/

class Solution {
  bstFromPreorder(preorder) {
    return this.buildBST(preorder, { idx: 0 }, -Infinity, Infinity);
  }

  buildBST(preorder, ref, min, max) {
    if (ref.idx === preorder.length) return null;
    let value = preorder[ref.idx];
    if (!(value > min && value < max)) return null;
    let node = new TreeNode(value);
    ref.idx++;
    node.left = this.buildBST(preorder, ref, min, value);
    node.right = this.buildBST(preorder, ref, value, max);
    return node;
  }
}
```

